submitOB02() {
  state.errors = {};
  const name = (state.draft.name || '').trim();
  if (!name) {
    state.errors.name = 'Please enter your LLC legal business name.';
    this.renderErrors();
    return;
  }
  const stateCode = (state.draft.formationState || '').toUpperCase().trim();
  const validState = US_STATES.find(s => s.code === stateCode);
  if (!stateCode || !validState) {
    state.errors.name = 'Please select a supported U.S. formation state or territory.';
    this.renderErrors();
    return;
  }
  state.draft.formationState = validState.code;
  state.draft.formationStateDisplay = validState.name;

  if (!isValidIsoDate(state.draft.formationDate)) {
    state.errors.name = 'Please select a valid formation date (YYYY-MM-DD).';
    this.renderErrors();
    return;
  }
  if (!isValidIsoDate(state.draft.bookkeepingStartDate)) {
    state.errors.name = 'Please select a valid bookkeeping start date (YYYY-MM-DD).';
    this.renderErrors();
    return;
  }
  // Domain rule: no formation/start date ordering check
  this.goto('OB-03', state.draft.memberMode || 'default');
},

