renderErrors() {
  const ob02Error = document.getElementById('ob02-error');
  const ob03Error = document.getElementById('ob03-error');
  const screenOb03 = document.getElementById('screen-ob-03');
  const nameInput = document.getElementById('llc-name-input');
  const stateTrigger = document.getElementById('state-select-trigger');
  const formDateTrigger = document.getElementById('formation-date-trigger');
  const booksDateTrigger = document.getElementById('books-date-trigger');

  if (nameInput) {
    nameInput.classList.toggle('error', !!state.errors.name);
    nameInput.setAttribute('aria-invalid', !!state.errors.name);
  }
  if (stateTrigger) {
    stateTrigger.classList.toggle('error', !!state.errors.state);
    stateTrigger.setAttribute('aria-invalid', !!state.errors.state);
  }
  if (formDateTrigger) {
    formDateTrigger.classList.toggle('error', !!state.errors.formationDate);
    formDateTrigger.setAttribute('aria-invalid', !!state.errors.formationDate);
  }
  if (booksDateTrigger) {
    booksDateTrigger.classList.toggle('error', !!state.errors.booksDate);
    booksDateTrigger.setAttribute('aria-invalid', !!state.errors.booksDate);
  }

  const ob02Msg = state.errors.name || state.errors.state || state.errors.formationDate || state.errors.booksDate;
  if (ob02Msg) {
    ob02Error.textContent = ob02Msg;
    ob02Error.classList.add('active');
  } else {
    ob02Error.textContent = '';
    ob02Error.classList.remove('active');
  }

  if (state.errors.members) {
    ob03Error.textContent = state.errors.members;
    ob03Error.classList.add('active');
    if (screenOb03) screenOb03.classList.add('has-error');
  } else {
    ob03Error.textContent = '';
    ob03Error.classList.remove('active');
    if (screenOb03) screenOb03.classList.remove('has-error');
  }
},

