patches.new:
if (!this._keyBound) {
  this._keyBound = true;
  document.addEventListener('keydown', (e) => {
    if (state.openPicker) {
      if (e.key === 'Escape') {
        e.preventDefault();
        window.pilot.closeModals();
        return;
      }
      if (e.key === 'Tab') {
        const activeModal = document.getElementById('modal-' + state.openPicker);
        if (activeModal) {
          const focusables = Array.from(activeModal.querySelectorAll('button:not([disabled]), input:not([disabled]), [tabindex]:not([tabindex="-1"])')).filter(el => el.offsetParent !== null);
          if (focusables.length > 0) {
            const first = focusables[0];
            const last = focusables[focusables.length - 1];
            if (e.shiftKey) {
              if (document.activeElement === first || !activeModal.contains(document.activeElement)) {
                e.preventDefault();
                last.focus();
              }
            } else {
              if (document.activeElement === last || !activeModal.contains(document.activeElement)) {
                e.preventDefault();
                first.focus();
              }
            }
          }
        }
      }
    }
  });
}
